private typealias E = EvidenceSeed

/// Follow-up trials for batch BK stories: the same defendant, back in this court.
extension FollowUpCases {
    static let batchBK: [CaseTemplate] = [kitchenStrangulationBack, contractorDepositsBack, taxPreparerBack, sellPillsAtWorkBack, vanCocaineBack, barBrokenBottleBack, cyclistHitAndRunBack, burnedCarBack, fenceLineBack, evidenceRoomBack, witnessThreatBack, missingToddlerBack, informantBuyBack, coldCaseGenealogyBack, wrongApartmentBack, affluenzaCrashBack, showerStabbingBack, hiredTeenBack, jailSmugglingBack, arsenicWidowBack, textingSuicideBack, moonshineExplosionBack, huntingAccidentBack, copperTheftBack, bingoHallBack, deedForgeryBack, groceryFallBack]

    static let kitchenStrangulationBack = SmallCases.make(
        key: "story.followup.kitchenStrangulationBack",
        category: .family,
        headlines: ["Protective Order Violated at Ex-Partner's Gym", "Defendant From Kitchen Case Charged With Contact Violation"],
        law: "dvpoViolation",
        spec: "Willfully violated a domestic violence protective order by going to a gym where {V} was exercising, on {DATE}.",
        ages: 26...53,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} walked into a fitness center where {V} was on a treadmill and sat in the lobby for half an hour, in violation of a protective order that bars contact. The front desk called deputies. {DL} says {D.he} had a trial membership and did not know {V} would be there.",
        state: [E(.video, 3, "Gym Lobby Camera", "{D} sits facing the treadmill row for thirty minutes."), E(.document, 2, "Protective Order", "An order barring {D} from being near {V} in any public place.")],
        defense: [E(.document, 1, "Trial Membership", "A new trial membership card in {D}'s name issued that morning.")],
        role: "Gym front desk worker",
        exam: [.direct("What is your job?", "\"I work the front desk at a fitness center, where I check members in and watch the lobby.\""), .direct("What happened that morning?", "\"A man came in and sat in the lobby, facing the treadmill row, where a member was exercising.\""), .direct("What did you notice?", "\"{D.He} stayed there for thirty minutes without using any equipment, just watching one person.\""), .direct("Who was the person?", "\"{V}, who told me {V.he} had a protective order against {DL} and who was shaking.\""), .direct("What did you do?", "\"I called the sheriff's office, and deputies arrived within ten minutes.\""), .direct("What does the gym camera show?", "\"{DL} sitting in the lobby and staring at {V} on the treadmill for the whole half hour.\""), .cross("{DL} had a membership card?", "\"Yes, {D.he} had a new trial membership card that had been issued that same morning.\""), .cross("{DL} didn't speak to {V}?", "\"No, {D.he} never spoke to {V}, and never moved from the chair in the lobby.\""), .cross("{DL} didn't touch {V}?", "\"No. {DL} didn't touch {V}.\""), .cross("{DL} left when the deputies came?", "\"Yes, {D.he} left without argument when the deputies walked in and asked {D.him} to go.\""), .cross("The gym is a public place?", "\"Yes, the gym is open to members, and anyone with a membership can walk in.\"")],
        theory: ("{D} went where the order forbade.", "A trial membership and bad luck."),
        allocution: "\"I take responsibility for what happened at that fitness center. I'd gotten a trial membership to start working out, and I didn't know {V} would be there. I've been in this courtroom before, and I know the order says to stay away. I should have left the moment I saw {V.him}, and I'm sorry.\"",
        truths: ("{DL} asked a mutual friend which gym {V} used and signed up the same day.", "The gym's records show {D} signed up before {V}'s visit and {V}'s schedule changed that morning."),
        defendant: [.direct("Did you go to the gym where {V} was?", "\"I did, but I didn't know {V.he} was there. I had signed up for a trial membership.\""), .direct("Why did you sit in the lobby?", "\"I was waiting for a friend to arrive. I didn't notice who was on the treadmill.\""), .direct("Did you know about the protective order?", "\"Yes, I knew about it. I should have checked who was there before going.\""), .direct("Did you watch {V}?", "\"I may have looked at the treadmills. I didn't realize it was {V.him}.\""), .direct("What did you do when the deputies came?", "\"I told them what I was doing. I left right away.\""), .direct("What would you tell {V}?", "\"I'm sorry for frightening you. I didn't know you were there.\""), .cross("You've violated a protective order before, haven't you?", "\"Yes, and I told the court I'd keep away. I broke that promise.\""), .cross("You signed up for a trial membership at the gym where she works out?", "\"I did sign up for a trial membership at that gym, and I can't explain the coincidence.\""), .cross("You sat for thirty minutes facing the treadmill row?", "\"I did sit there for thirty minutes facing the row, and I know how it looked.\""), .cross("You'll stay away from the gym?", "\"Yes, I'll follow every term of the protective order, from this day on.\""), .cross("You'll follow the order?", "\"Yes. I'll follow the order exactly.\"")],
        openings: ("{D} walked into a fitness center where {V} was on a treadmill and sat in the lobby for half an hour in violation of a protective order that bars contact, and the front desk called deputies, and {DL} had stood in this court in {PRIORDATE} over {PRIOR}.", "The defense will say {D} had a trial membership and did not know {V} would be at the center. {D} came to exercise, not to contact {V}."),
        closings: ("The protective order bars contact, {D} sat in the lobby for half an hour where {V} was on the treadmill, and since {PRIOR}, {DL} could not have missed what the order means.", "A trial membership at a gym is not an intent to find {V}. The State must prove {D} knew {V} would be there and stayed."),
        timeline: [(-30, "The protective order is entered."), (0, "{D} signs up at the gym."), (0, "Deputies arrive.")],
        identified: "A front desk worker's 911 call.",
        mood: .wantsConviction)

    static let contractorDepositsBack = SmallCases.make(
        key: "story.followup.contractorDepositsBack",
        category: .whiteCollar,
        headlines: ["Storm Tarp Deposit Vanishes With Contractor", "Remodeler From Deposit Case Charged Again"],
        law: "falsePretenses",
        spec: "Obtained $4,200 from {V} by false pretenses, a promise to repair a storm-damaged roof, on {DATE}.",
        ages: 35...66,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, following a hailstorm, {D} told {V}, a retiree, that a crew would be out within a week to repair the roof and took $4,200 in cash up front. No crew came and {DL}'s phone went dead. {DL} says materials were backordered and a refund was coming.",
        state: [E(.document, 3, "Signed Estimate", "An estimate signed by {D} for $4,200 with a start date of 'next Monday.'"), E(.digital, 2, "Text Messages", "Texts from {V} go unanswered for three weeks.")],
        defense: [E(.document, 1, "Supplier Order", "A supplier order form for shingles dated the day after the deposit.")],
        role: "Retired homeowner",
        exam: [.direct("What happened to your roof?", "\"A hailstorm damaged it badly, and I had leaks in two rooms. I needed a repair quickly.\""), .direct("Who did you hire?", "\"{DL}, who came to my door a day after the storm and said a crew would come within a week.\""), .direct("What did you pay?", "\"Forty-two hundred dollars in cash up front, because {D.he} said the materials had to be ordered immediately.\""), .direct("What does the signed estimate say?", "\"Forty-two hundred dollars for the repair, with a start date of 'next Monday,' signed by {DL}.\""), .direct("What happened?", "\"No crew came, and {DL}'s phone went dead. I tried calling for three weeks.\""), .direct("What did {DL} say?", "\"{D.He} said materials were delayed and that {D.he} had ordered shingles from a supplier.\""), .cross("You're retired?", "\"Yes, I'm retired and on a fixed income, and that money was most of my savings.\""), .cross("You paid cash because {DL} asked?", "\"Yes, I'll stop taking cash deposits, and I'll only accept payment when work is complete.\""), .cross("You've been repaid?", "\"No, I haven't been repaid a single dollar, and {D.his} phone number is disconnected.\""), .cross("Other neighbors paid too?", "\"I heard from several neighbors that they paid {D.his} deposits as well, after the hailstorm.\""), .cross("The roof leaked again?", "\"Yes, the roof leaked again during the next storm, and the ceiling in the den fell in.\"")],
        theory: ("{D} took a deposit for work never meant to start.", "A backorder, not a scheme."),
        allocution: "\"I should have known better than to take that cash before the shingles arrived. They were backordered, and then my phone broke, and I couldn't reach {V}. I've been in this courtroom before, and I know that doesn't excuse it. I'm sorry for the weeks {V.he} spent under a damaged roof, and I'll refund the money.\"",
        truths: ("The supplier order was cancelled the same afternoon it was placed.", "The supplier confirms the order was a real one and the shingles were delayed by a plant shutdown."),
        defendant: [.direct("Did you take the deposit and not do the work?", "\"I took the deposit and ordered materials. I meant to do the work, but the supplier was late.\""), .direct("What happened with the supplier?", "\"They said the shingles were backordered for weeks. I couldn't start without them.\""), .direct("Why didn't you tell the homeowner?", "\"I was embarrassed. I should have called. I let my phone go dead.\""), .direct("Did you plan to cheat {V.him}?", "\"No. I planned to do the roof. I got overwhelmed with storm jobs.\""), .direct("Where did the money go?", "\"Some to the supplier, and some to my own bills. I don't have it all.\""), .direct("What would you tell the homeowner?", "\"I'm sorry for the delay and the leaks. I'll repay the forty-two hundred dollars.\""), .cross("You've been convicted of taking deposits before, haven't you?", "\"Yes, and the judge made me promise that this would not happen again. I'm ashamed.\""), .cross("You told {V.him} a crew would come within a week?", "\"I did say a crew would be there within a week, and that wasn't true.\""), .cross("You didn't answer {V.his} calls for three weeks?", "\"I didn't answer {V.his} calls for three weeks, and that was wrong of me.\""), .cross("You'll repay {V.him}?", "\"Yes, I'll repay the forty-two hundred dollars, in installments, as soon as the court sets them.\""), .cross("You'll stop taking deposits?", "\"Yes, I'll stop taking cash deposits, and I'll only accept payment when the work is complete.\"")],
        openings: ("Following a hailstorm, {D} told {V}, a retiree, that a crew would be out within a week to repair the roof and took $4,200 in cash up front, and no crew came and {D}'s phone went dead, and {DL} had already appeared here in {PRIORDATE} over {PRIOR}.", "The defense will say materials were backordered after the storm and a refund was coming, and {D} did not mean to cheat {V}. A shortage after a hailstorm is common."),
        closings: ("{V} paid $4,200 in cash, no crew came, {D}'s phone went dead, and after {PRIOR} {DL} understood exactly what taking cash after a storm from a retiree means.", "A backorder after a storm is an ordinary delay, and a refund was coming. The State must prove {D} never intended to do the work."),
        timeline: [(-4, "Hail damages the roof."), (0, "{V} hands over $4,200."), (21, "{V} calls deputies.")],
        identified: "The retiree's report.",
        mood: .wantsConviction)

    static let taxPreparerBack = SmallCases.make(
        key: "story.followup.taxPreparerBack",
        category: .whiteCollar,
        headlines: ["Preparer Forged Client's Signature on Refund Loan", "Tax Office Owner Back in Court on Forgery Count"],
        law: "forgery",
        spec: "Forged the signature of {V} on a refund-advance loan form, on {DATE}.",
        ages: 30...64,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D}, now running a smaller tax office in a strip mall, signed {V}'s name on a refund-advance loan form that sent $1,900 to {DL}'s own account. {V} learned of it when the lender called. {DL} says {V} orally approved the form and said to sign.",
        state: [E(.document, 3, "Loan Form", "A refund-advance form with {V}'s name signed in {D}'s handwriting style."), E(.forensic, 2, "Handwriting Exam", "An examiner says the signature matches {D}'s writing, not {V}'s.")],
        defense: [E(.statement, 1, "Verbal Approval", "{DL} says {V} told {D.him} on the phone to sign.")],
        role: "Lender fraud investigator",
        exam: [.direct("What is your position?", "\"I'm a fraud investigator for a lender that offers refund-advance loans to people who file their taxes early.\""), .direct("What did you discover?", "\"A loan form with a customer's name signed on it, which sent nineteen hundred dollars to an account belonging to {DL}.\""), .direct("Who was the customer?", "\"{V}, who told me {V.he} never applied for a loan, and who learned about it only when our company called.\""), .direct("What does the loan form show?", "\"{V}'s name signed in a handwriting style that doesn't match {V}'s own, with {DL}'s tax office listed as the preparer.\""), .direct("What did the handwriting examiner find?", "\"That the signature matches {DL}'s known handwriting, and that it is not {V}'s signature.\""), .direct("What did {DL} say?", "\"{D.He} said {V} gave verbal approval over the phone for {D.him} to sign for {V.him}.\""), .cross("Preparers sometimes sign for clients?", "\"Not on a loan form, without a written authorization on file with our company.\""), .cross("{V} had been a client of {DL}?", "\"Yes, for two years, so {D.he} had {V.his} personal information.\""), .cross("The money went straight to {DL}'s account?", "\"Yes, to an account in {D.his} own name, not to {V}.\""), .cross("{DL} runs a small office in a strip mall?", "\"Yes, and the office has been open for about a year.\""), .cross("{DL} hasn't repaid the lender?", "\"No, {D.he} hasn't repaid it, and the loan is now in default with the lender.\"")],
        theory: ("{D} forged a client's name to take a loan.", "A client who approved and forgot."),
        allocution: "\"I signed that refund-advance form with {V}'s approval, or so I understood it, and the money went to my office for fees owed. I've been in this courtroom before, and I should have gotten it in writing. I'll sort it out with the lender and {V.him}.\"",
        truths: ("{DL} had asked {V} for approval and was refused two days earlier.", "A call log shows a four-minute call from {V}'s number the day before."),
        defendant: [.direct("Did you sign the customer's name?", "\"Yes, I did, but only because {V.he} told me on the phone that it was fine. I believed I had {V.his} approval.\""), .direct("When did {V.he} say that?", "\"A week before, when we talked about speeding up {V.his} refund. {V.He} said, 'Just do whatever you need to.'\""), .direct("Why did the money go to your account?", "\"The loan was supposed to cover my fees first, and then I'd send {V.him} the rest. I never got to that step.\""), .direct("Did you plan to keep it?", "\"No. I planned to give {V.him} what was left after fees. I got behind on my own bills and delayed.\""), .direct("What did you do when the lender called?", "\"I told them the truth about the phone call, and I offered to repay the whole amount.\""), .direct("What would you tell the customer and the lender?", "\"I'm sorry for signing your name. I should have gotten your approval in writing.\""), .cross("You've been disciplined by the state before for tax preparation violations, haven't you?", "\"Yes, and I was told to keep written authorization for everything. I didn't keep it for this one.\""), .cross("A phone call isn't a written authorization, is it?", "\"No, it isn't, and I know now that it wasn't enough for a loan form.\""), .cross("Nineteen hundred dollars went into your own account instead of {V.his}?", "\"It did, and I know how that looks to the court and to {V.him}.\""), .cross("You'll repay the entire amount to the lender?", "\"Yes, I'll repay all nineteen hundred dollars, and I'll start paying this month.\""), .cross("You'll close your tax office if the court says so?", "\"Yes, if the court says so, I'll close the office and stop preparing returns.\"")],
        openings: ("{D}, now running a smaller tax office in a strip mall, signed {V}'s name on a refund-advance loan form that sent $1,900 to {D}'s own account, and {V} learned of it when the lender called, and this was not {DL}'s first time here, after {PRIOR} in {PRIORDATE}.", "The defense will say {V} approved the form orally and told {D} to sign. {D} signed with {V}'s permission, and signed only what {V} told {D.him} to sign, after a call to the lender about a loan {V} wanted."),
        closings: ("The loan form carries {V}'s name signed by {D}, $1,900 went to {D}'s account, and with {PRIOR} behind {D.him}, {DL} knew what signing for a client requires.", "An oral approval from a client who said to sign is a permission. The State must prove {V} did not say so."),
        timeline: [(-2, "{V} refuses the loan."), (0, "The form is signed."), (12, "The lender calls {V}.")],
        identified: "The lender's call to {V}.",
        mood: .wantsConviction)

    static let sellPillsAtWorkBack = SmallCases.make(
        key: "story.followup.sellPillsAtWorkBack",
        category: .drugs,
        headlines: ["Pills Found in Glovebox Pill Bottle Marked for Someone Else", "Warehouse Worker From Pill Case Charged Again"],
        law: "possSchedII",
        spec: "Possessed oxycodone, a Schedule II controlled substance, on {DATE}.",
        ages: 24...66,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a trooper stopped {D} for a broken tail light on {DATE} and smelled nothing but found a pill bottle in the glovebox marked with another person's name, holding eleven oxycodone tablets. {DL} says a cousin left it and {D.he} meant to throw it out.",
        state: [E(.physical, 3, "Pill Bottle", "A bottle labeled for another person with eleven oxycodone tablets.", .search), E(.video, 2, "Dash Camera", "{D} reaches toward the glovebox when the trooper approaches.")],
        defense: [E(.statement, 1, "Cousin's Bottle", "{DL} says a cousin left the bottle in the car.")],
        role: "State trooper",
        exam: [.direct("What is your assignment?", "\"I'm a state trooper who patrols highways and makes traffic stops, including at night.\""), .direct("Why did you stop {DL}?", "\"A tail light was broken, and the car was swerving a little, so I stopped it to check on the driver.\""), .direct("What happened at the car window?", "\"I noticed {DL} reaching toward the glove compartment as I walked up, which made me cautious.\""), .direct("What did you find in the glove compartment?", "\"A pill bottle labeled for another person, holding eleven oxycodone tablets, a Schedule II controlled substance.\""), .direct("What does your dash camera show?", "\"{DL} leaning toward the glovebox before I reached the window, and then sitting back with both hands on the wheel.\""), .direct("What did {DL} say?", "\"{D.He} said a cousin left the bottle in the car and that {D.he} didn't know it was there.\""), .cross("The bottle had someone else's name?", "\"Yes, a person I could not match to {DL} or to any relative that {D.he} named.\""), .cross("You didn't smell alcohol or drugs on {DL}?", "\"No, I smelled nothing, and {D.he} seemed alert, and answered questions clearly.\""), .cross("{DL} gave permission to search?", "\"Yes, {D.he} agreed when I asked, and {D.he} stepped out calmly.\""), .cross("The car belongs to {DL}?", "\"Yes, the car belongs to {D.him}, and it was registered in {D.his} name with current tags.\""), .cross("The tablets were counted?", "\"Yes, I counted eleven tablets, and the lab later confirmed that they were oxycodone.\"")],
        theory: ("{D} held pills with no prescription.", "A cousin's bottle, not {D.his}."),
        allocution: "\"That bottle with someone else's name on it belonged to my cousin, and I forgot it in the glovebox when I meant to throw it out. I've been in this courtroom before, and I know how that looks in a traffic stop. I'm sorry, and I'll get rid of anything I find.\"",
        truths: ("{DL}'s thumbprint was on the lid of the bottle.", "The named owner says the bottle was lost from the cousin's car, not from {DL}'s."),
        defendant: [.direct("Did you know the pills were in the glovebox?", "\"No. A cousin was in my car a few days before, and I think he left the bottle there.\""), .direct("Why did you reach toward the glovebox?", "\"I was reaching for my registration, which I keep in there. I didn't think about the pill bottle.\""), .direct("Whose name was on the bottle?", "\"A person I don't know. My cousin may have gotten it from someone else.\""), .direct("Do you take oxycodone?", "\"No, I've never had a prescription for it. I used to have a problem years ago, but I've been clean.\""), .direct("What did you do when the trooper found it?", "\"I told him it wasn't mine, and I gave him my cousin's name.\""), .direct("What would you tell the trooper?", "\"I'm sorry for the trouble. I didn't know the bottle was in my car, and I'll help find out whose it is.\""), .cross("You've been convicted of possessing a controlled substance before, haven't you?", "\"Yes, and I told the court I'd stay away from pills. I didn't know about this one.\""), .cross("You reached for the glovebox as the trooper approached?", "\"I did, and I can see how that looked, but I only wanted my papers.\""), .cross("A bottle of oxycodone with someone else's name was in your car?", "\"It was, and I can't explain how it got there, except through my cousin.\""), .cross("Your cousin will say it was his?", "\"I hope so, and I'll ask him to talk to the trooper.\""), .cross("You'll take a drug test?", "\"Yes, I'll take a drug test today, and as often as the court wants me to.\"")],
        openings: ("A trooper stopped {D} for a broken tail light, smelled nothing, and found a pill bottle in the glovebox marked with another person's name, holding eleven oxycodone tablets, and {DL} had faced this court in {PRIORDATE} over {PRIOR}.", "The defense will say a cousin left the bottle in the car and {D} meant to throw it out. {D} did not sell or use any pills."),
        closings: ("Eleven oxycodone tablets in a bottle with another person's name were in {D}'s glovebox, and after {PRIOR} {DL} knew exactly what holding them means.", "A cousin's bottle in a glovebox is not {D}'s possession by choice. The State must prove {D} knew the pills were there and kept them."),
        timeline: [(0, "A tail light is out."), (0, "The traffic stop."), (0, "The glovebox is searched.")],
        identified: "A traffic stop.",
        mood: .indifferent)

    static let vanCocaineBack = SmallCases.make(
        key: "story.followup.vanCocaineBack",
        category: .drugs,
        headlines: ["Cocaine Found in Dry Box at Lake Boat Ramp", "Cargo Van Defendant Charged With New Drug Count"],
        law: "possSchedII",
        spec: "Possessed cocaine, a Schedule II controlled substance, on {DATE}.",
        ages: 24...63,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a wildlife officer checking boats at a lake ramp on {DATE} found 12 grams of cocaine in a dry box on {D}'s boat. {DL} says the boat was borrowed that weekend and the box was never opened.",
        state: [E(.physical, 3, "Dry Box", "A sealed dry box holding twelve grams of cocaine in bags.", .search), E(.statement, 2, "Boat Owner", "The owner says {D} had the boat all weekend.")],
        defense: [E(.statement, 1, "Borrowed Boat", "{DL} says {D.he} borrowed the boat and never opened the box.")],
        role: "Wildlife officer",
        exam: [.direct("What is your assignment?", "\"I'm a wildlife officer, and I check boats, licenses, and safety equipment at the lake ramps.\""), .direct("What happened at the ramp?", "\"I was checking boats coming in, and I asked {DL} to open the dry box on {D.his} boat for a safety inspection.\""), .direct("What did you find in the dry box?", "\"A sealed bag holding twelve grams of what looked like cocaine, packed in smaller bags.\""), .direct("What did the lab report say?", "\"That the substance was cocaine, a Schedule II controlled substance, with a weight of twelve grams.\""), .direct("Who owns the boat?", "\"A friend of {DL}'s, according to the registration, who told me that {DL} had the boat all weekend.\""), .direct("What did {DL} say?", "\"{D.He} said {D.he} borrowed the boat that weekend and never opened the box.\""), .cross("The box was sealed?", "\"Yes, with a latch, and it hadn't been opened recently by the look of it.\""), .cross("{DL} didn't appear nervous?", "\"{D.He} seemed relaxed and chatty, until I opened the box and found the bag.\""), .cross("The owner wasn't on the boat?", "\"No, the owner wasn't on the boat, and {DL} was alone when I checked it.\""), .cross("{DL} gave a name for the owner?", "\"Yes, {D.he} gave a name, and the owner confirmed that he had lent the boat.\""), .cross("{DL} didn't flee?", "\"No, {D.he} didn't flee. {D.He} stayed at the ramp and answered all my questions.\"")],
        theory: ("{D} had cocaine on the boat {D.he} used.", "A borrowed boat, a box never opened."),
        allocution: "\"I take responsibility for lending my name to that boat trip, but I borrowed that boat for the weekend, and I never opened the dry box. I've been in this courtroom before, and I know my history comes first to people's minds. I'm sorry for the trouble at the ramp, and I'll cooperate fully.\"",
        truths: ("{DL}'s fingerprints are on the bags inside the box.", "The owner admits a friend used the boat the weekend before and left the box."),
        defendant: [.direct("Did you know about the cocaine in the box?", "\"No. The boat belongs to a friend, and I borrowed it for the weekend. I never opened the dry box.\""), .direct("What did you keep in the box?", "\"Nothing. I didn't use it. I kept my own gear in a separate bag under the seat.\""), .direct("Why did you hand the box to the officer?", "\"{OFF.He} asked me to open it, and I didn't have the key. {OFF.He} opened it {OFF.himself}.\""), .direct("Do you use cocaine?", "\"No. I've never used it, and I haven't been around it in years.\""), .direct("What did you do when the officer found it?", "\"I told him I had no idea, and I gave him my friend's name.\""), .direct("What would you tell the officer?", "\"I'm sorry for the trouble. I'll cooperate and help find who put it there.\""), .cross("You've been convicted of a drug offense before, haven't you?", "\"Yes, and I told the court I'd stay away from it. I didn't put this in the box.\""), .cross("The owner says you had the boat all weekend?", "\"I did, and I can't explain how the bag got there, except that someone else may have used the boat before.\""), .cross("Twelve grams of cocaine is a lot?", "\"It is, and I can see why this is serious.\""), .cross("You'll take a drug test?", "\"Yes, I'll take a drug test today, and I'll take any other test the court asks for.\""), .cross("You'll give the officer your phone?", "\"Yes, I'll hand the officer my phone, and I'll let {OFF.him} read every message on it.\"")],
        openings: ("A wildlife officer checking boats at a lake ramp found 12 grams of cocaine in a dry box on {D}'s boat. {DL} came before this court in {PRIORDATE} over {PRIOR}, and the lab confirms the cocaine.", "The defense will say the boat was borrowed that weekend and the dry box was never opened. {D} did not know what was inside."),
        closings: ("The lab confirms 12 grams of cocaine in the dry box on {D}'s boat, and with {PRIOR} already on {D.his} record, {DL} knew exactly what that box held.", "A borrowed boat carries what its owner left. The State must prove {D} knew the cocaine was in the dry box, and the weekend borrower never mentioned the box."),
        timeline: [(-2, "{D} borrows the boat."), (0, "The ramp check."), (0, "The box is opened.")],
        identified: "A routine boat check.",
        mood: .indifferent)

    static let barBrokenBottleBack = SmallCases.make(
