        ages: 18...68,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} was told a refill would not be ready for two hours on {DATE} and shoved {V}, a pharmacy clerk, back into a shelf of cough syrup. {V} had a bruised shoulder. {DL} says {V} slammed the counter window on {D.his} hand first.",
        state: [E(.video, 3, "Pharmacy Camera", "{D} reaches over the counter and shoves {V} backward."), E(.statement, 2, "Customer in Line", "A customer says {D} pushed {V} first.")],
        defense: [E(.statement, 1, "Window Slammed", "{DL} says {V} slammed the counter window on {D.his} hand.")],
        role: "Pharmacy clerk",
        exam: [.direct("What is your job?", "\"I'm a pharmacy clerk, and I fill refills and answer questions at the counter.\""), .direct("What happened?", "\"A customer asked about a refill, and I told him it wouldn't be ready for two hours because of a delay.\""), .direct("How did {DL} react?", "\"{D.He} got angry, shouted, and reached over the counter and shoved me backward into a shelf of cough syrup.\""), .direct("What was your injury?", "\"A bruised shoulder and a sore back, and a few bottles broke when I fell against the shelf.\""), .direct("What does the pharmacy camera show?", "\"{DL} reaching over the counter and shoving me, and me stumbling back into the shelf.\""), .direct("What did {DL} say?", "\"{D.He} said I slammed the counter window on {D.his} hand first.\""), .cross("The window was partly closed?", "\"Yes, I was closing it when {D.he} pushed {D.his} hand through.\""), .cross("You didn't hit {DL}?", "\"No, I never touched {D.him}, and I never hit {D.his} hand with the window.\""), .cross("A customer in line saw it?", "\"Yes, a customer in line saw it, and the customer said {DL} pushed first.\""), .cross("{DL} left after the shove?", "\"Yes, {D.he} left the pharmacy before the deputy arrived, and didn't come back.\""), .cross("The refill was important to {DL}?", "\"I believe it was, since it was a regular medication that {D.he} needed each month.\"")],
        theory: ("{D} shoved a pharmacy clerk.", "A reaction to a slammed window."),
        allocution: "\"I'm sorry for the trouble I caused at that pharmacy window. I was told my refill would take two hours, and the clerk slammed the window on my hand, and I pushed back into the shelf. I've been in this courtroom before, and I know I should have walked away. I'm sorry about the shoulder.\"",
        truths: ("{DL} had been told three times that the refill needed a doctor's approval.", "The video shows the counter window closing on {DL}'s hand before the shove."),
        defendant: [.direct("Did you shove the pharmacy clerk?", "\"Yes, I did, but {V.he} slammed the window on my hand first. I reacted without thinking.\""), .direct("What happened to your hand?", "\"It was caught in the window, and it hurt badly. I jerked it out and pushed {V.him}.\""), .direct("Why were you angry?", "\"I needed my medication, and I'd been told it would take two hours. I was in pain, and I lost my temper.\""), .direct("Did you mean to hurt {V.him}?", "\"No. I didn't mean to push {V.him} into the shelf. I only wanted {V.him} away from the window.\""), .direct("What did you do after?", "\"I left. I felt terrible. I came back later to apologize, but the store was closed.\""), .direct("What would you tell the clerk?", "\"I'm sorry for pushing you. I'll pay for the broken bottles and your medical costs.\""), .cross("You've been charged with an assault at a store before, haven't you?", "\"Yes, and I told the court I'd keep my temper. I didn't.\""), .cross("The video shows you reaching over the counter first?", "\"It does show me reaching over the counter, and I can't deny what it shows.\""), .cross("A customer says you pushed first?", "\"{V.He} does say I pushed first, and I understand why {V.he} thinks so.\""), .cross("You'll pay for the damage?", "\"Yes, I'll pay for the broken bottles and for the clerk's doctor bills.\""), .cross("You'll stay away from that pharmacy?", "\"Yes, I'll stay away from that pharmacy and use a different one from now on.\"")],
        openings: ("{D} was told a refill would not be ready for two hours and shoved {V}, a pharmacy clerk, back into a shelf of cough syrup, and {V} had a bruised shoulder, and {DL} had been before this court in {PRIORDATE} over {PRIOR}.", "The defense will say {V} slammed the counter window on {D}'s hand first, and {D} pushed in reaction. A man whose hand is caught in a window may push."),
        closings: ("The clerk had a bruised shoulder from the shove into the shelf, and having faced {PRIOR} before, {DL} understood exactly how to wait for a refill without putting hands on anyone.", "A hand slammed in a window is a painful provocation. The State must prove {D} meant to shove {V} and not to free {D.himself}."),
        timeline: [(0, "The refill is delayed."), (0, "The shove."), (0, "Deputies take statements.")],
        identified: "Pharmacy camera video.",
        mood: .indifferent)

    static let cyclistHitAndRunBack = SmallCases.make(
        key: "story.followup.cyclistHitAndRunBack",
        category: .traffic,
        headlines: ["Driver Raced Freight Train Over Crossing, Deputies Say", "Hit-and-Run Defendant Charged With Reckless Driving"],
        law: "recklessDriving",
        spec: "Drove a motor vehicle on a highway carelessly and heedlessly in willful disregard of the safety of others, on {DATE}.",
        ages: 40...70,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a railroad crew reported that a pickup swerved around lowered crossing gates and beat a freight train by seconds on {DATE}. A deputy traced the truck to {D}. {DL} says the gates were stuck and the lights never flashed.",
        state: [E(.video, 3, "Locomotive Camera", "A pickup drives around the lowered gate seconds ahead of the train."), E(.document, 2, "Railroad Report", "The engineer reports the gates were down and lights flashing.")],
        defense: [E(.document, 1, "Maintenance Log", "A log shows a signal fault at the crossing last month.")],
        role: "Locomotive engineer",
        exam: [.direct("What is your position?", "\"I'm a locomotive engineer, and I drive freight trains along the line through several counties.\""), .direct("What happened at the crossing?", "\"The gates were down and the lights were flashing when a pickup drove around the gate and crossed in front of my train.\""), .direct("How close was it?", "\"Only a few seconds. I sounded the horn and applied the brakes, but a train that size can't stop quickly.\""), .direct("What does the locomotive camera show?", "\"A pickup swerving around the lowered gate, crossing the tracks, and clearing them just before we arrived.\""), .direct("How was the truck identified?", "\"A deputy traced the plate on the video to a pickup registered to {DL}.\""), .direct("What did {DL} say?", "\"{D.He} said the gates were stuck and that {D.he} thought they were malfunctioning.\""), .cross("There was a signal fault last month?", "\"Yes, there is a maintenance log showing a fault at that crossing.\""), .cross("The gates were down this time?", "\"Yes, they were fully lowered, and the lights were flashing.\""), .cross("No one was hurt?", "\"No one was hurt, though it was extremely close, and I could see the truck's face.\""), .cross("You reported the truck?", "\"Yes, I reported the truck to dispatch as soon as we had stopped the train.\""), .cross("{DL} didn't stop for the gates?", "\"No, {D.he} didn't stop for the gates. {D.He} drove around them at speed.\"")],
        theory: ("{D} drove around lowered gates.", "A faulty crossing signal."),
        allocution: "\"I drove across those tracks believing the gates were stuck halfway, and the lights never flashed. I've been in this courtroom before, and I know I should have stopped and waited. I'm sorry for the scare to the railroad crew, and I'm grateful nobody was hurt.\"",
        truths: ("The camera shows the signal lights flashing red as the pickup passes.", "A repair crew found the signal worked normally that day."),
        defendant: [.direct("Did you drive around the gate?", "\"Yes, I did. I thought the gates were broken, because they had been faulty before, and I was late.\""), .direct("Why did you think they were broken?", "\"They've gotten stuck before, and last month they stayed down for an hour with no train.\""), .direct("Did you see the train?", "\"I saw a light, but I thought it was far away. I misjudged how close it was.\""), .direct("Why were you in a hurry?", "\"I was late for work, and I took a chance. I know that was foolish.\""), .direct("What did you do after crossing?", "\"I kept going. I was shaking, and I didn't stop. I regret that.\""), .direct("What would you tell the engineer?", "\"I'm sorry for scaring you. I could have caused a terrible accident.\""), .cross("You've been cited for a railroad crossing violation before, haven't you?", "\"Yes, and I told the court I'd never drive around a gate again. I did.\""), .cross("The gates were down and the lights were flashing?", "\"They were down and flashing, and I drove around them anyway, and I regret it.\""), .cross("A train can't stop in time?", "\"It can't stop in time, and that's exactly why the gates are there.\""), .cross("You'll take a driving course?", "\"Yes, I'll take a driving course, and I'll pay any fine the court sets for me.\""), .cross("You'll never drive around a gate again?", "\"Never again. I'll wait for every train, however long it takes, for the rest of my life.\"")],
        openings: ("A railroad crew reported that a pickup swerved around lowered crossing gates and beat a freight train by seconds, and a deputy traced the truck to {D}, and {DL} had stood in this court in {PRIORDATE} over {PRIOR}.", "The defense will say the gates were stuck and the lights never flashed, and {D} did not know a train was coming. A broken signal is not a driver's choice."),
        closings: ("The crew saw the pickup swerve around lowered gates and beat the train by seconds, the truck is {D}'s, and since {PRIOR}, {DL} could not have missed what lowered gates mean.", "A signal that never flashed is a railroad failure. The State must prove {D} knew the gates were down when {D.he} drove around them."),
        timeline: [(-30, "A signal fault is logged."), (0, "The pickup drives around the gates."), (1, "A deputy traces the truck to {D}.")],
        identified: "The locomotive camera.",
        mood: .wantsConviction)

    static let burnedCarBack = SmallCases.make(
        key: "story.followup.burnedCarBack",
        category: .whiteCollar,
        headlines: ["Pontoon Boat Reported Stolen Turns Up in Relative's Barn", "Burned-Truck Claimant Faces New Insurance Fraud Charge"],
        law: "insuranceFraud",
        spec: "Presented a false insurance claim for a pontoon boat reported stolen, on or about {DATE}.",
        ages: 26...53,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} reported {D.his} pontoon boat stolen from a marina slip and filed a $23,000 claim. Deputies found the boat under a tarp in a relative's barn after a tip. {DL} says the relative moved it for winter without telling {D.him}.",
        state: [E(.physical, 3, "Boat in the Barn", "The pontoon boat is found under a tarp in a relative's barn.", .search), E(.document, 2, "Insurance Claim", "A signed claim stating the boat was stolen from slip 14.")],
        defense: [E(.statement, 1, "Relative Moved It", "{DL} says the relative moved the boat for winter.")],
        role: "Insurance investigator",
        exam: [.direct("What is your position?", "\"I'm an insurance investigator, and I look into claims for stolen vehicles and boats.\""), .direct("What was the claim?", "\"A claim for twenty-three thousand dollars for a pontoon boat that {DL} said had been stolen from a marina slip.\""), .direct("What did you find?", "\"After a tip, deputies found the pontoon boat under a tarp in a barn belonging to {DL}'s relative.\""), .direct("How soon after the loss was the claim filed?", "\"A few days after the date listed on the sworn statement.\""), .direct("What does the barn search show?", "\"The boat, with the same registration number and the same damage listed in the claim, hidden in the barn.\""), .direct("What did {DL} say?", "\"{D.He} said the relative moved the boat for the winter, and that {D.he} didn't know.\""), .cross("The relative owns the barn?", "\"Yes, the barn belongs to a cousin, who lives out of town most of the year.\""), .cross("The boat wasn't damaged?", "\"No, the boat wasn't damaged, and it was in good condition under the tarp.\""), .cross("{DL} didn't try to sell it?", "\"Not that we found, so there's no sign that {D.he} meant to sell it.\""), .cross("{DL} reported it stolen quickly?", "\"Within a day, and filed the claim two days later.\""), .cross("{DL} cooperated?", "\"Partly. {D.He} answered my questions, but {D.he} wouldn't give me his cousin's number.\"")],
        theory: ("{D} hid a boat to collect $23,000.", "A relative moved it unannounced."),
        allocution: "\"I take responsibility for filing that claim too fast. I thought my pontoon boat was stolen when it wasn't in the slip, and a relative had moved it for winter without telling me. I'll withdraw it and cooperate with the insurer.\"",
        truths: ("The marina's gate log shows {D}'s truck towing the boat out two days before the claim.", "The marina's gate log shows only the relative's truck towing the boat out."),
        defendant: [.direct("Did you file a false claim?", "\"I filed a claim because I thought the boat was stolen. I didn't know my cousin moved it.\""), .direct("Why did your cousin move it?", "\"He said he'd take it to his barn for winter, but he didn't tell me. I assumed it was stolen when I saw the empty slip.\""), .direct("Did you check with your cousin?", "\"No. I should have called him. I panicked and reported it.\""), .direct("Did you plan to collect insurance?", "\"No. I thought the boat was gone. I was upset.\""), .direct("What did you do when the investigator told you?", "\"I admitted the mistake and offered to withdraw the claim.\""), .direct("What would you tell the insurer?", "\"I'm sorry for the mistake. I'll withdraw the claim and repay any money.\""), .cross("You've been charged with a false insurance claim before, haven't you?", "\"Yes, and I told the court I'd be careful. I should have called my cousin.\""), .cross("You swore the boat was stolen from a slip on a specific night?", "\"I did swear the boat was stolen, and I was wrong to say so.\""), .cross("The boat was hidden under a tarp in a barn?", "\"It was, and I can't explain it except for my cousin.\""), .cross("You'll repay anything you received?", "\"Yes, I'll repay any money that the insurer paid me for this claim.\""), .cross("You'll withdraw the claim?", "\"Yes, I'll withdraw the claim in writing today, and I'll apologize to the insurer.\"")],
        openings: ("{D} reported {D}'s pontoon boat stolen from a marina slip and filed a $23,000 claim, and deputies found the boat under a tarp in a relative's barn after a tip, and {DL} had already appeared here in {PRIORDATE} over {PRIOR}.", "The defense will say a relative moved the boat for the winter without telling {D}, and {D} honestly believed it was stolen. {D} did not hide it."),
        closings: ("The boat was under a tarp in a relative's barn, {D} filed a $23,000 claim, and after {PRIOR} {DL} understood exactly what a false theft claim is.", "A relative who moved the boat without telling the owner caused a mistaken report. The State must prove {D} knew where the boat was."),
        timeline: [(-2, "The boat leaves the marina."), (0, "{D} files the claim."), (25, "The boat is found.")],
        identified: "An anonymous tip.",
        mood: .wantsConviction)

    static let fenceLineBack = SmallCases.make(
        key: "story.followup.fenceLineBack",
        category: .property,
        headlines: ["Neighbor's Pecan Trees Cut Down Along New Property Line", "Fence Dispute Defendant Faces Property Charge"],
        law: "injuryRealProperty",
        spec: "Willfully and wantonly injured the real property of {V}, four pecan trees valued at $2,400, on {DATE}.",
        ages: 68...84,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, after moving to a smaller lot, {D} cut down four pecan trees along the line shared with {V} on {DATE}. The trees were valued at $2,400. {DL} says the trunks stood on {D.his} side of a new survey.",
        state: [E(.video, 3, "Trail Camera", "{D} runs a chainsaw at the tree line and loads limbs onto a truck."), E(.document, 2, "Plat", "A county plat placing the trees on {V}'s side of the line.")],
        defense: [E(.document, 1, "Survey Stake", "A private survey stake placing the line past the trees.")],
        role: "Neighboring landowner",
        exam: [.direct("What is your property?", "\"A tract of land that borders {DL}'s former lot, where four large pecan trees stood along the line.\""), .direct("What happened?", "\"{DL} cut down all four pecan trees one afternoon, with a chainsaw, and loaded the limbs onto a truck.\""), .direct("What was the value?", "\"About twenty-four hundred dollars, since the trees were mature and produced nuts every year.\""), .direct("What does the trail camera show?", "\"{DL} running a chainsaw along the tree line and loading limbs into a truck bed.\""), .direct("What does the county plat show?", "\"That the trees stood on my side of the line, by about six feet.\""), .direct("What did {DL} say?", "\"{D.He} said the trunks stood on {D.his} side, based on a private survey stake.\""), .cross("{DL} had moved to a smaller lot?", "\"Yes, and {D.he} still owned the old lot for a time.\""), .cross("The survey stake is private?", "\"Yes, it was put in by {DL}'s own surveyor, and not by the county.\""), .cross("{DL} didn't ask before cutting?", "\"No, {D.he} didn't ask me before cutting them, and I didn't know until I came home.\""), .cross("The trees were healthy?", "\"Yes, they were healthy, and they shaded my yard and gave nuts every fall.\""), .cross("{DL} offered to pay?", "\"Not yet. {D.He} hasn't offered to pay anything toward the trees.\"")],
        theory: ("{D} cut trees on {V}'s land.", "Trees on {D}'s side of a survey."),
        allocution: "\"I should have known better than to cut those pecan trees. They stood on my side of a new survey, and I didn't need them. I've been in this courtroom before about a tree, and I should have waited and talked to {V} first. I'll help pay what they were worth.\"",
        truths: ("{DL} was shown the county plat a month before and was told to leave the trees.", "The county plat was filed with an error that a re-survey later corrected in {DL}'s favor."),
        defendant: [.direct("Did you cut down the pecan trees?", "\"I did, because I believed they were on my side of the line. My survey stake showed that.\""), .direct("Where was the stake?", "\"Past the trees, according to my surveyor. I trusted the stake and didn't check the county plat.\""), .direct("Did you ask the neighbor?", "\"No. I should have. I was in a hurry to clear the lot before moving.\""), .direct("Did you know the trees were valuable?", "\"I knew they were pecan trees, but I didn't think about the value.\""), .direct("What did you do when your neighbor complained?", "\"I told him about the stake. When I saw the plat, I knew I was wrong.\""), .direct("What would you tell your neighbor?", "\"I'm sorry for cutting your trees. I'll pay twenty-four hundred dollars.\""), .cross("You've been in a boundary dispute before, haven't you?", "\"Yes, and I told the court I'd settle lines in court. I didn't.\""), .cross("You relied on a private stake instead of the county plat?", "\"I did rely on a private stake, and that was a mistake.\""), .cross("You cut four mature trees without asking?", "\"I did, and I wish I had not. The survey seemed clear to me, and I did not think about the shade those trees gave.\""), .cross("You'll pay the full value?", "\"Yes, I'll pay the full twenty-four hundred dollars for the trees to my neighbor.\""), .cross("You'll plant replacement trees?", "\"Yes, if he wants, I'll plant replacement trees on his side of the line.\"")],
        openings: ("After moving to a smaller lot, {D} cut down four pecan trees along the line shared with {V}, trees valued at $2,400, and this was not {DL}'s first time here, after {PRIOR} in {PRIORDATE}.", "The defense will say the trunks stood on {D}'s side of a new survey, so the trees were {D}'s to cut. {D} relied on the survey."),
        closings: ("The pecan trees stood along the shared line and were worth $2,400, and with {PRIOR} behind {D.him}, {DL} knew where the line ran and what stood on it.", "A man who relies on a new survey cuts his own trees. The State must prove {D} knew the trees were {V}'s."),
        timeline: [(-30, "A new survey is stamped."), (0, "The trees come down."), (1, "{V} reports the loss.")],
        identified: "A trail camera.",
        mood: .divided,
        genders: ["D": .male])

    static let evidenceRoomBack = SmallCases.make(
        key: "story.followup.evidenceRoomBack",
        category: .whiteCollar,
        headlines: ["Youth Baseball League Treasurer Missing $9,000", "Former Evidence Custodian Charged With Taking League Funds"],
        law: "embezzlement",
        spec: "Embezzled $9,000 entrusted to {D} as treasurer of a youth baseball league, on or about {DATE}.",
        ages: 38...63,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, the new treasurer of a youth baseball league, {D}, kept the league's checking account. A board audit on {DATE} found $9,000 withdrawn in cash over a season with no receipts. {DL} says the money paid for equipment and umpires in cash.",
        state: [E(.document, 3, "Bank Statements", "Nine cash withdrawals totaling $9,000 signed by {D}."), E(.document, 2, "Board Audit", "The audit finds no receipts or invoices for any withdrawal.")],
        defense: [E(.statement, 1, "Cash for Umpires", "{DL} says the league pays umpires and vendors in cash.")],
        role: "League board president",
        exam: [.direct("What is your role?", "\"I'm the president of the board of a youth baseball league, and I oversee the officers and the books.\""), .direct("Who was the treasurer?", "\"{DL}, who joined the board that season and kept the league's checking account.\""), .direct("What did the audit find?", "\"Nine cash withdrawals totaling nine thousand dollars over a season, with no receipts or invoices for any of them.\""), .direct("What do the bank statements show?", "\"Nine withdrawals, each signed by {DL}, in amounts from five hundred to fifteen hundred dollars.\""), .direct("What did the board audit conclude?", "\"That there was no record of what the cash had been used for, and no approval by the board.\""), .direct("What did {DL} say?", "\"{D.He} said the league pays umpires and vendors in cash, and that the cash went to them.\""), .cross("Umpires are paid in cash?", "\"Sometimes, but we have a form for each payment, which {DL} didn't turn in.\""), .cross("The league has gotten receipts before?", "\"Yes, we've gotten receipts every year from the previous treasurer, with no trouble.\""), .cross("{DL} is new to the board?", "\"Yes, this was {D.his} first season on the board, and {D.he} was learning the job.\""), .cross("{DL} offered to find the receipts?", "\"{D.He} said so, more than once, but none have ever come to me.\""), .cross("The league's budget was tight?", "\"Yes, the budget was tight, and we had to cancel a tournament in the fall.\"")],
        theory: ("{D} took league money.", "Cash spent on the league."),
        allocution: "\"I'm sorry for the trouble I caused the league. The nine thousand dollars I withdrew in cash paid for umpires and equipment, and I kept the cash in a box without receipts. I've been in this courtroom before as a treasurer, and I should have documented it. I'll account for every dollar.\"",
        truths: ("{DL} deposited $6,000 of the cash into a personal account.", "{DL}'s shoebox of receipts was later found at the concession stand."),
        defendant: [.direct("Did you take the league's money?", "\"I withdrew the cash, but I paid it to umpires and vendors. I thought I had receipts, and I lost them.\""), .direct("Who did you pay?", "\"Umpires, a field maintenance crew, and a few vendors. I wrote the amounts in a notebook.\""), .direct("Where is the notebook?", "\"I lost it. It was in my truck, and I can't find it now.\""), .direct("Did you keep any for yourself?", "\"A little, for expenses, and I should have asked. I thought it was allowed.\""), .direct("What did you do when the board asked?", "\"I told them I'd find the receipts, and I looked, but I couldn't find them.\""), .direct("What would you tell the board and the parents?", "\"I'm sorry for the confusion and for losing the receipts. I'll repay what I can't account for.\""), .cross("You've been accused of misusing funds in another club, haven't you?", "\"Yes, and I was cleared. I know why it comes up.\""), .cross("Nine thousand dollars in cash with no receipts is a lot?", "\"It is a lot, and I understand the board's concern about it.\""), .cross("You lost your notebook?", "\"I did lose the notebook, and I can't prove anything without it.\""), .cross("You'll repay the league?", "\"Yes, I'll repay the league, on a plan that the board agrees to.\""), .cross("You'll resign as treasurer?", "\"Yes, I'll resign as treasurer today, and hand over the checkbook to the board.\"")],
        openings: ("The new treasurer of a youth baseball league, {D}, kept the league's checking account, and a board audit found $9,000 withdrawn in cash over a season with no receipts, and {DL} had faced this court in {PRIORDATE} over {PRIOR}.", "The defense will say the money paid for equipment and umpires in cash, as small leagues do, and {D} did not keep any of it. A cash payment is not a theft."),
        closings: ("The audit found $9,000 in cash withdrawals with no receipts, {D} kept the account, and after {PRIOR} {DL} knew exactly what a treasurer's records must show.", "Small leagues pay umpires and vendors in cash all the time. The State must prove {D} kept the $9,000 and did not spend it for the league."),
        timeline: [(-180, "{D} becomes treasurer."), (0, "The audit begins."), (10, "Deputies are called.")],
        identified: "A board audit.",
        mood: .wantsConviction)

