        headlines: ["Paint Thrown on Former Roommate's Door and Porch", "Shower Case Defendant Charged With Vandalism"],
        law: "injuryRealProperty",
        spec: "Willfully and wantonly injured real property of {V}, a front door and porch, valued at $520, on {DATE}.",
        ages: 27...38,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, red paint was thrown on the door and porch of {V}'s rental on {DATE}, causing $520 in damage. A doorbell camera showed a figure in a gray hood. {DL} says the figure was someone else and {D.he} was home.",
        state: [E(.video, 3, "Doorbell Camera", "A figure in a gray hood throws paint on the door and porch."), E(.physical, 2, "Paint Can", "A can of the same red paint found in {D}'s trunk.", .search)],
        defense: [E(.statement, 1, "Home That Night", "{DL} says {D.he} was at home and the paint was left over from a project.")],
        role: "Renter",
        exam: [.direct("What is your home?", "\"A rental house, where I've lived for a year, with a front door and a porch.\""), .direct("What happened?", "\"One night someone threw red paint all over my front door and porch.\""), .direct("What was the damage?", "\"Five hundred twenty dollars to repaint the door and clean the porch, which I had to pay.\""), .direct("What does the doorbell camera show?", "\"A figure in a gray hood throwing a can of paint at the door, then running.\""), .direct("How was {DL} identified?", "\"A can of the same red paint was found in the trunk of {DL}'s car, when deputies searched it.\""), .direct("What did {DL} say?", "\"{D.He} said {D.he} was home that night, and the paint was left over from a project.\""), .cross("The figure's face isn't visible?", "\"No, the hood hid the face, and the picture is dark and grainy.\""), .cross("Red paint is common?", "\"Yes, red paint is common, but the shade matches the can in the trunk.\""), .cross("{DL} is a neighbor?", "\"{D.He} lives a few streets away from my rental, so it's close.\""), .cross("You've had a dispute with {DL}?", "\"Yes, we've had a dispute with {D.him} over a parking spot, for months.\""), .cross("The paint stained the wood?", "\"Yes, the paint stained the wood, and the door had to be sanded.\"")],
        theory: ("{D} threw paint on a door.", "Someone else in a gray hood."),
        allocution: "\"I'm sorry for the trouble I caused, though I wasn't the person in that gray hood. I was home that night, and the paint is from a fence project I did last month. I've been in this courtroom before, and I know that points toward me. I'm sorry for the damage to {V}'s rental.\"",
        truths: ("{DL} had threatened {V} over unpaid rent that week.", "A neighbor's camera shows a person of a different build walking up the street at that time."),
        defendant: [.direct("Did you throw paint on the door?", "\"No. I was at home that night. The paint in my trunk was left over from a project.\""), .direct("What project?", "\"I painted a shed last month, and the extra paint stayed in my trunk.\""), .direct("Who can say you were home?", "\"My roommate can say it. He was with me all evening at home.\""), .direct("Why would someone do this to the renter?", "\"I don't know. I had a parking dispute with {V.him}, but I'd never do that.\""), .direct("What did you do when the deputy found the can?", "\"I told {OFF.him} about the shed and showed {OFF.him} the paint-stained brush.\""), .direct("What would you tell the renter?", "\"I'm sorry for the damage. It wasn't me, and I hope you find who did it.\""), .cross("You've been charged with vandalism before, haven't you?", "\"Yes, and I promised the court I'd cut it out for good. I'm not doing that now.\""), .cross("Red paint matching the shade was in your trunk?", "\"It was in my trunk, and I know how that looks to the court.\""), .cross("Your roommate is your alibi?", "\"He is my alibi, and I understand that he's not independent.\""), .cross("You'll let deputies search your home?", "\"Yes, I'll let deputies search my home, my truck, and my garage.\""), .cross("You'll avoid the renter?", "\"Yes, I'll stay away from the renter and from the street where {V.he} lives.\"")],
        openings: ("Red paint was thrown on the door and porch of {V}'s rental, causing $520 in damage, and a doorbell camera showed a figure in a gray hood, and {DL} had been before this court in {PRIORDATE} over {PRIOR}.", "The defense will say the figure was someone else, and {D} was home that night. A gray hood on a camera is not a face."),
        closings: ("The doorbell camera shows a figure in a gray hood throw paint, $520 of damage followed, and with {PRIOR} already on {D.his} record, {DL} knew exactly whose rental it was.", "A hood hides a face, and {D} was home. The State must prove {D} was the figure on the camera, and a gray hood is worn by hundreds of people in town."),
        timeline: [(-3, "A rent dispute."), (0, "Night: the paint is thrown."), (1, "{V} finds the door.")],
        identified: "A doorbell camera.",
        mood: .indifferent,
        genders: ["D": .female])

    static let hiredTeenBack = SmallCases.make(
        key: "story.followup.hiredTeenBack",
        category: .whiteCollar,
        headlines: ["Burglary Claim for Jewelry Questioned by Insurer", "School Official From Earlier Case Charged With Insurance Fraud"],
        law: "insuranceFraud",
        spec: "Presented a false renter's insurance claim for stolen jewelry, on or about {DATE}.",
        ages: 22...32,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} filed a $9,400 renter's claim for jewelry said to be stolen in a burglary on {DATE}. The insurer found the same pieces listed for sale online. {DL} says a friend sold the pieces without permission.",
        state: [E(.digital, 3, "Online Listings", "Listings of the same jewelry, posted days before the burglary report."), E(.document, 2, "Claim Form", "A sworn claim listing the pieces as stolen.")],
        defense: [E(.statement, 1, "Friend Sold Them", "{DL} says a friend took and sold the pieces.")],
        role: "Insurance investigator",
        exam: [.direct("What is your position?", "\"I'm an insurance investigator, and I review claims for fraud, especially jewelry claims.\""), .direct("What was the claim?", "\"A renter's claim for nine thousand four hundred dollars for jewelry said to be stolen in a burglary.\""), .direct("What did you find online?", "\"Listings for the same jewelry pieces, posted days before the burglary was reported.\""), .direct("What proof of ownership came with the claim?", "\"A list of the pieces and a few photos, but no appraisal or receipts.\""), .direct("What does that mean?", "\"That the jewelry was for sale before it was supposedly stolen, which suggests the burglary was staged.\""), .direct("What did {DL} say?", "\"{D.He} said a friend took and sold the pieces without {D.his} permission.\""), .cross("The listings were under {DL}'s name?", "\"Under an account in a friend's name, not in {DL}'s name.\""), .cross("There was a police report?", "\"Yes, a burglary report was filed with the sheriff's office on the same day.\""), .cross("The jewelry was valuable?", "\"Some pieces were valuable, and the claim total was nine thousand four hundred dollars.\""), .cross("{DL} didn't make the listings?", "\"{D.He} says so, but I haven't found proof that the friend made the listings.\""), .cross("{DL} cooperated?", "\"Partly. {D.He} answered some questions but declined to give me the friend's address.\"")],
        theory: ("{D} claimed jewelry that was for sale.", "A friend sold it without asking."),
        allocution: "\"A friend sold those pieces online without my permission, and I filed the claim believing they were stolen. I've been in this courtroom before about a similar matter, and I know it looks bad. I'm sorry for the insurer's trouble.\"",
        truths: ("The listing account's recovery email is {DL}'s.", "The listing account was created from a friend's phone on the same network."),
        defendant: [.direct("Did you file a false claim?", "\"I filed a claim for jewelry I thought was stolen. I didn't know my friend had sold it.\""), .direct("Who is the friend?", "\"A man who stayed with me. I'll give his name and number to the investigator.\""), .direct("When did he take the jewelry?", "\"Before the burglary report. I didn't know until I found the listings.\""), .direct("Why did you report a burglary?", "\"The jewelry was gone, and I thought someone had broken in. I called the sheriff.\""), .direct("What did you do when the investigator showed you the listings?", "\"I admitted I'd made a mistake, and I offered to withdraw the claim.\""), .direct("What would you tell the insurer?", "\"I'm sorry for the claim. I'll withdraw it and repay anything.\""), .cross("You've been charged with a false claim before, haven't you?", "\"Yes, and I promised the court I'd be more careful from then on. I should have checked.\""), .cross("The listings were posted days before the burglary report?", "\"They were posted days before the report, and I can't explain it.\""), .cross("You swore the jewelry was stolen in a burglary?", "\"I did swear the jewelry was stolen, and I was wrong to say so.\""), .cross("You'll withdraw the claim?", "\"Yes, I'll withdraw the claim in writing, and I'll apologize to the insurer.\""), .cross("You'll repay the insurer?", "\"Yes, I'll repay the insurer anything it paid me, with interest.\"")],
        openings: ("{D} filed a $9,400 renter's claim for jewelry said to be stolen in a burglary, and the insurer found the same pieces listed for sale online, and {DL} had stood in this court in {PRIORDATE} over {PRIOR}.", "The defense will say a friend sold the pieces without permission, and {D} did not know the jewelry had been sold. {D} did not lie about the burglary."),
        closings: ("The insurer found the same pieces listed for sale online, {D} filed a $9,400 claim, and having faced {PRIOR} before, {DL} understood exactly what a sworn claim means.", "A friend who sold the jewelry without permission is the one who made the sale. The State must prove {D} knew the jewelry was not stolen."),
        timeline: [(-6, "The jewelry is listed online."), (0, "A burglary is reported."), (9, "The insurer finds the listings.")],
        identified: "An insurer's online search.",
        mood: .wantsConviction,
        genders: ["D": .female])

    static let jailSmugglingBack = SmallCases.make(
        key: "story.followup.jailSmugglingBack",
        category: .drugs,
        headlines: ["Forged Refill at Pharmacy Drive-Thru Leads to Fraud Charge", "Detention Officer From Smuggling Case Charged Again"],
        law: "prescriptionFraud",
        spec: "Obtained a controlled substance by forgery of a prescription, on {DATE}.",
        ages: 25...42,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} presented a refill for hydrocodone at a pharmacy drive-thru on {DATE}. The doctor's office said it never wrote it. {DL} says a friend handed over the slip as genuine.",
        state: [E(.document, 3, "Refill Slip", "A slip with a doctor's name signed in a different hand."), E(.video, 2, "Drive-Thru Camera", "{D} hands over the slip and signs for the bottle.")],
        defense: [E(.statement, 1, "Handed the Slip", "{DL} says a friend gave {D.him} the slip and said it was real.")],
        role: "Pharmacist",
        exam: [.direct("What is your job?", "\"I'm a pharmacist, and I work the drive-thru window, where customers drop off refill slips and pick up medicine.\""), .direct("What happened that day?", "\"A customer handed in a refill slip for hydrocodone, signed for the bottle, and drove away with it.\""), .direct("What made you suspicious?", "\"The doctor's name on the slip was signed in a different hand than the doctor's usual signature on file.\""), .direct("What did you do?", "\"I called the doctor's office afterward, and they said they never wrote the prescription.\""), .direct("What does the drive-thru camera show?", "\"{DL} handing over the slip, signing for the bottle, and taking the bag from my hand.\""), .direct("What did {DL} say?", "\"{D.He} said a friend handed {D.him} the slip and told {D.him} it was a real prescription.\""), .cross("You filled the prescription before you checked?", "\"Yes, because nothing looked wrong at the time and the line was long.\""), .cross("The slip looked real?", "\"It looked real at a glance, with the doctor's printed name and a seal.\""), .cross("{DL} signed for the medicine in {D.his} own name?", "\"Yes, {D.he} signed {D.his} real name and showed a valid license.\""), .cross("{DL} wasn't a regular customer?", "\"I had never seen {D.him} at our pharmacy before that day.\""), .cross("The friend hasn't been identified?", "\"{DL} gave a first name only, and we haven't been able to find that person.\"")],
        theory: ("{D} used a forged slip to get pills.", "A friend's slip, innocently used."),
        allocution: "\"I take responsibility for handing that slip to the pharmacy window. A friend gave it to me and told me it was genuine, and I never knew the doctor's office hadn't written it. I've been in this courtroom before, and I should have called the doctor myself.\"",
        truths: ("{DL} had been refused a refill at the same office two days earlier.", "The friend, when found, confirms {D} paid $40 for the slip knowing it was blank."),
        defendant: [.direct("Did you forge the prescription?", "\"No. A friend handed me the slip and told me it was a genuine refill, so I took it to the pharmacy.\""), .direct("Who is the friend?", "\"A man I know from the neighborhood who said he was out of town. I'll give his name and number to the deputy.\""), .direct("Why did he ask you to do it?", "\"He said he was too sick to drive, and he asked me to pick up his medicine.\""), .direct("Did you know the slip was forged?", "\"No. I thought it was real, and I signed for the bottle in my own name because I had nothing to hide.\""), .direct("Where is the bottle now?", "\"I gave it to my friend that evening, as I'd promised. I never took any of the pills.\""), .direct("What would you tell the pharmacist?", "\"I'm sorry for the trouble. I didn't know the slip was fake, and I'll help find the man who gave it to me.\""), .cross("You've been convicted of a prescription crime before, haven't you?", "\"Yes, and I told the court I'd never go near one again. I should have refused to carry the slip.\""), .cross("You signed for a bottle of hydrocodone that was prescribed to someone else?", "\"I did, and I should have asked why he couldn't pick it up himself.\""), .cross("You didn't verify the friend's story with the doctor?", "\"I didn't, and I regret that I trusted him without checking.\""), .cross("You'll give the deputy your phone and the messages from your friend?", "\"Yes, I'll hand over my phone today, with every message between us.\""), .cross("You'll stay away from that pharmacy and from the friend?", "\"Yes, I'll stay away from both, and I won't carry anything for anyone again.\"")],
        openings: ("{D} presented a refill for hydrocodone at a pharmacy drive-thru, and the doctor's office said it never wrote it, and {DL} had already appeared here in {PRIORDATE} over {PRIOR}.", "The defense will say a friend handed over the slip as genuine, and {D} believed it was a real prescription. {D} did not forge anything."),
        closings: ("The doctor's office never wrote the refill, {D} presented it at a drive-thru, and since {PRIOR}, {DL} could not have missed how a pharmacy checks a slip.", "A slip given by a friend as genuine looks like any slip. The State must prove {D} knew it was forged, and a drive-thru slip is a paper no one at the window can authenticate by sight."),
        timeline: [(-2, "{D} is refused a refill."), (0, "The drive-thru visit."), (0, "The pharmacist calls the doctor.")],
        identified: "A pharmacist's call.",
        mood: .indifferent)

    static let arsenicWidowBack = SmallCases.make(
        key: "story.followup.arsenicWidowBack",
        category: .whiteCollar,
        headlines: ["Elderly Neighbor Says $18,000 Went Missing After Helping With Bills", "Poisoning Case Defendant Charged With Exploiting Older Adult"],
        law: "exploitationElder",
        spec: "Knowingly obtained $18,000 from {V}, an older adult, by deception, on or about {DATE}.",
        ages: 56...68,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} began helping {V}, an elderly neighbor, with bills. By {DATE}, $18,000 had moved from {V}'s savings to {DL}'s account. {DL} says the money was a gift.",
        state: [E(.document, 3, "Bank Transfers", "Six transfers from {V}'s savings to an account in {D}'s name."), E(.statement, 2, "Bank Teller", "The teller says {V} seemed confused and {D} did the talking.")],
        defense: [E(.document, 1, "Gift Note", "A handwritten note signed 'for my friend, a gift.'")],
        role: "Neighbor's niece",
        exam: [.direct("How are you related to the victim?", "\"{V} is my aunt, an elderly woman who lives alone, and I check on {V.him} every few weeks.\""), .direct("What did you discover?", "\"That eighteen thousand dollars had left {V.his} savings account over about three months, in six separate transfers.\""), .direct("Where did the money go?", "\"To an account in {DL}'s name, a neighbor who had started helping my aunt with {V.his} bills.\""), .direct("What did the bank teller tell you?", "\"That my aunt seemed confused when {V.he} came in, and that {DL} did most of the talking for {V.him}.\""), .direct("How did your aunt explain it?", "\"{V.He} didn't remember the amounts, and {V.he} said {DL} had been so kind that {V.he} wasn't worried.\""), .direct("What did {DL} say?", "\"{D.He} said the money was a gift and showed a handwritten note that said 'for my friend, a gift.'\""), .cross("Your aunt has some memory problems?", "\"Yes, {V.he} has some memory problems, and they've gotten worse in the past year.\""), .cross("{DL} did help with her bills?", "\"Yes, for several months, and {D.he} drove {V.him} to appointments.\""), .cross("The note is in your aunt's handwriting?", "\"It looks like hers, though shaky, and I can't be sure.\""), .cross("Your aunt trusted {DL}?", "\"{V.He} did, completely, and {V.he} called {D.him} {V.his} best friend.\""), .cross("The money hasn't been returned?", "\"No, none of the money has been returned, though we've asked {D.him} several times.\"")],
        theory: ("{D} took an older adult's savings.", "A gift the family does not like."),
        allocution: "\"I should have known better than to take that money, even as a gift. I helped {V} with bills for months, and {V.he} insisted on giving it to me. I've been in this courtroom before, and I know how it looks to the family. I'll repay it.\"",
        truths: ("The gift note was written in {D}'s handwriting on {V}'s stationery.", "{V}'s doctor confirms {V} was clear-minded and often spoke of the gift."),
        defendant: [.direct("Did you take your neighbor's savings?", "\"No. {V.He} gave me the money as a gift. {V.He} wanted to thank me for all the help I gave {V.him}.\""), .direct("What help did you give her?", "\"I drove {V.him} to the doctor and the pharmacy, paid {V.his} bills, and sat with {V.him} when {V.he} was lonely.\""), .direct("Why did you speak for her at the bank?", "\"{V.He} was nervous, and {V.he} asked me to explain. I was only trying to help {V.him}.\""), .direct("Where is the note from?", "\"{V.He} wrote it {V.himself}, with my help, after {V.he} decided to give me the money.\""), .direct("Did you pressure her?", "\"No. I never asked for a dollar. {V.He} offered, and I accepted because {V.he} insisted.\""), .direct("What would you tell her niece?", "\"I'm sorry for the worry this caused. I only wanted to help, and I'll go along with whatever the court decides.\""), .cross("You've been accused of taking money from an elderly person before, haven't you?", "\"Yes, and I was cleared. I understand why people are suspicious of me.\""), .cross("Eighteen thousand dollars is a very large gift from a woman with memory loss, isn't it?", "\"It is, and I see now that I should have asked {V.him} family first.\""), .cross("The teller said she seemed confused?", "\"That's what the teller says, but {V.he} seemed fine to me when {V.he} signed.\""), .cross("You'll return the money if the court asks you to?", "\"Yes, I'll return every dollar of it, if that's what the court decides I should do.\""), .cross("You'll stay away from her and her accounts?", "\"Yes, I'll stay away from {V.his} accounts, and I'll visit only with {V.his} niece present.\"")],
        openings: ("{D} began helping {V}, an elderly neighbor, with bills, and by the time of the report $18,000 had moved from {V}'s savings to {D}'s account, and this was not {DL}'s first time here, after {PRIOR} in {PRIORDATE}.", "The defense will say the money was a gift from a neighbor who was grateful, freely given. {D} did not pressure {V}."),
        closings: ("$18,000 moved from an elderly neighbor's savings to {D}'s account while {D} helped with bills, and after {PRIOR} {DL} understood exactly what that trust means.", "A gift from a grateful neighbor is lawful. The State must prove {V} did not freely give the money and that {D} took advantage."),
        timeline: [(-180, "{D} begins helping {V}."), (0, "The sixth transfer."), (20, "The niece reports it.")],
        identified: "A relative's report.",
        mood: .wantsConviction,
        genders: ["D": .female])

    static let textingSuicideBack = SmallCases.make(
        key: "story.followup.textingSuicideBack",
        category: .cyber,
        headlines: ["Home Address and Daily Route Posted in Gaming Server", "Texting Case Defendant Faces Cyberstalking Charge"],
        law: "cyberstalking",
        spec: "Used electronic communication to harass {V} by posting {V.his} address and daily route in an online server, on or about {DATE}.",
        ages: 18...26,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V}, a teammate in an online gaming group, found {V.him} home address and daily route posted in the group's server through {DATE}, with dozens of mocking messages. {DL} says {D.he} was only a member and others posted it.",
        state: [E(.digital, 3, "Server Logs", "Posts of {V}'s address and route sent from {D}'s account."), E(.document, 2, "Messages", "Forty-one messages from {D}'s account mocking {V}.")],
        defense: [E(.statement, 1, "Shared Access", "{DL} says several members shared the account.")],
        role: "Gaming group teammate",
        exam: [.direct("How do you know {DL}?", "\"We're both members of an online gaming group that plays together most evenings.\""), .direct("What did you find in the group's server?", "\"My home address and my daily route to work, posted in a channel that everyone in the group could see.\""), .direct("How did that make you feel?", "\"Frightened. I live alone, and I didn't know who might show up at my door after reading it.\""), .direct("What did the server logs show?", "\"The posts were sent from {DL}'s account, along with dozens of mocking messages about me.\""), .direct("How many messages were there?", "\"Forty-one messages from {DL}'s account, all making fun of me or of where I live.\""), .direct("What did {DL} say?", "\"{D.He} said several members shared the account, so anyone could have posted.\""), .cross("The account has {DL}'s name on it?", "\"Yes, it's registered under {D.his} name and {D.his} email address.\""), .cross("You've argued with {DL} before?", "\"Yes, we argued before, over a game, a few weeks earlier, and it got heated.\""), .cross("You reported it to the group's moderators?", "\"Yes, and they removed the posts, but not before many people saw them.\""), .cross("You changed your routine afterward?", "\"Yes, I changed my route to work and installed a camera at my door.\""), .cross("{DL} didn't threaten you directly?", "\"No, but posting my address felt like a threat to me.\"")],
        theory: ("{D} posted {V}'s address and mocked {V.him}.", "Posts by others using a shared login."),
        allocution: "\"I was only a member of that gaming group, and others used my login to post {V}'s address and route. I've been in this courtroom before about messages, and I know how that looks. I never wrote those mocking messages, and I'll leave the server.\"",
        truths: ("{DL}'s phone sent the login codes for the account each night.", "Two other members' logins appear on the server beside {DL}'s account."),
        defendant: [.direct("Did you post {V}'s address and route?", "\"No. Several members shared my account, so any of them could have posted from it.\""), .direct("Who shared your account?", "\"A few friends from the group, who used it when they wanted to join a game on my console.\""), .direct("Why did you share it?", "\"It was a casual thing among friends. We all shared passwords, and I never thought it was risky.\""), .direct("Did you write the mocking messages?", "\"A few of them were mine, and I regret them. The ones with the address weren't mine.\""), .direct("What did you do when you saw the posts?", "\"I told the group to delete them, and I changed my password the same day.\""), .direct("What would you tell {V}?", "\"I'm sorry for the posts and the messages. I'll stay out of your way, and I'll help find who posted the address.\""), .cross("You've been charged with harassing someone online before, haven't you?", "\"Yes, and I told the judge last time that I would change, and I meant it. Some of those messages were mine.\""), .cross("Forty-one messages from your account mocked {V}?", "\"They did, and I can't say all of them weren't mine.\""), .cross("You let others use your account and took no responsibility for what they posted?", "\"I did, and that was a bad decision that I regret.\""), .cross("You'll give the deputy the names of the others who used it?", "\"Yes, I'll give the deputy every name I can remember of the people who used my account.\""), .cross("You'll delete the account?", "\"Yes, I'll delete the account today, and I'll stay away from that gaming group for good.\"")],
        openings: ("{V}, a teammate in an online gaming group, found {V}'s home address and daily route posted in the group's server through the date of the report, with dozens of mocking messages, and {DL} had faced this court in {PRIORDATE} over {PRIOR}.", "The defense will say {D} was only a member of the group and others posted the address and the messages. {D} did not post the route."),
        closings: ("The address and daily route were posted in a server {D} belonged to, with dozens of mocking messages, and with {PRIOR} behind {D.him}, {DL} knew how that feels to {V}.", "Membership in a group is not authorship of a post. The State must prove {D} posted the address or the messages, and posts in a group server are written by whoever types them."),
        timeline: [(-12, "The first post."), (0, "The posts continue."), (2, "{V} reports them.")],
        identified: "Server logs.",
        mood: .divided,
        genders: ["D": .female])

    static let moonshineExplosionBack = SmallCases.make(
        key: "story.followup.moonshineExplosionBack",
        category: .publicOrder,
        headlines: ["Hounds Found Without Water in Backyard Pen", "Moonshine Case Defendant Charged With Animal Cruelty"],
        law: "animalCruelty",
        spec: "Intentionally failed to provide adequate water and shelter to four hunting dogs, on {DATE}.",
        ages: 45...70,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, an animal control officer found four hunting hounds in a backyard pen on {DATE} with an empty water pan, no shade, and temperatures in the nineties. {DL} says the water had been knocked over an hour earlier.",
        state: [E(.physical, 3, "Empty Pen", "An empty water pan, dry mud, and no shade in the pen.", .search), E(.video, 2, "Officer's Camera", "The dogs pant heavily and drink from a hose.")],
        defense: [E(.statement, 1, "Water Knocked Over", "{DL} says the pan was knocked over an hour earlier.")],
        role: "Animal control officer",
        exam: [.direct("What is your assignment?", "\"I'm an animal control officer, and I respond to complaints about neglected or mistreated animals.\""), .direct("What was reported?", "\"A neighbor complained that four hounds were left outside in the heat, without water, barking and panting.\""), .direct("What did you find at the pen?", "\"Four hunting dogs in a backyard pen, with an empty water pan, dry mud, and no shade at all.\""), .direct("What was the temperature?", "\"In the nineties, and the pen sat in direct sun, with no shelter anywhere.\""), .direct("What does your camera show?", "\"The dogs panting heavily, and then drinking greedily from a hose when I gave them water.\""), .direct("What did {DL} say?", "\"{D.He} said the water pan had been knocked over about an hour before I arrived.\""), .cross("The pan could have been knocked over?", "\"It could have, but the mud was dry, so it had been empty for hours.\""), .cross("The dogs were thin?", "\"They were lean, as hunting hounds often are, but not starved.\""), .cross("{DL} gave the dogs water when you asked?", "\"Yes, {D.he} turned on the hose right away when I asked, and let the dogs drink.\""), .cross("The dogs had a doghouse?", "\"No, there was no doghouse or shelter of any kind in the pen, only bare dirt.\""), .cross("The dogs recovered?", "\"Yes, after water and a few hours in the shade.\"")],
        theory: ("{D} left dogs without water in the heat.", "A water pan knocked over an hour ago."),
        allocution: "\"I filled that water pan at noon, and it was full when I left, and I believe the hounds knocked it over an hour before the officer came. I've been in this courtroom before about my dogs, and I love them. I'll add shade and a second pan.\"",
        truths: ("{DL} had been given a warning for the same pen two weeks earlier.", "A neighbor saw {DL} fill the pan at noon, an hour before the officer came."),
        defendant: [.direct("Did you deprive the dogs of water?", "\"I didn't mean to. The water pan was knocked over, and I didn't know until the officer came.\""), .direct("When did you last check on them?", "\"In the morning, about five hours earlier. The pan was full then.\""), .direct("Why was there no shade?", "\"I've been meaning to build a shelter, but I've been busy at work. I should have done it.\""), .direct("Did you see the dogs suffering?", "\"No. I was inside, and I didn't see them. If I had, I'd have helped at once.\""), .direct("What did you do when the officer arrived?", "\"I gave the dogs water from the hose and moved them to the shade of the porch.\""), .direct("What would you tell the officer?", "\"I'm sorry for the neglect. I'll build a shelter and add a second water pan.\""), .cross("You've been cited for neglecting animals before, haven't you?", "\"Yes, and I told the court I'd take better care. I should have checked more often.\""), .cross("It was in the nineties, and the pen had no shade or water?", "\"It did, and I know that was dangerous for the dogs.\""), .cross("The mud around the pan was dry?", "\"It was, which means the pan had been empty a while.\""), .cross("You'll build a shelter this week?", "\"Yes, I'll build a proper shelter with a roof, this week.\""), .cross("You'll let the officer inspect the pen again?", "\"Yes, I'll let the officer inspect the pen again, any time, without any notice.\"")],
        openings: ("An animal control officer found four hunting hounds in a backyard pen with an empty water pan and no shade in temperatures in the nineties. {DL} came before this court in {PRIORDATE} over {PRIOR}, and the officer's photos are in evidence.", "The defense will say the water had been knocked over an hour earlier, and {D} was about to refill it. {D} did not mean to leave the dogs without water."),
        closings: ("Four hounds were in a pen with an empty pan and no shade in the nineties, they were {D}'s dogs, and after {PRIOR} {DL} knew exactly what they need.", "A pan knocked over an hour earlier is a short lapse. The State must prove {D} knowingly left the dogs without water."),
        timeline: [(-14, "A warning about the pen."), (0, "1 p.m.: the officer arrives."), (0, "The dogs are examined.")],
