        genders: ["D": .male])

    static let huntingAccidentBack = SmallCases.make(
        key: "story.followup.huntingAccidentBack",
        category: .property,
        headlines: ["Hunter Found on Posted Farmland Without Permission", "Hunting Accident Defendant Faces Trespass Charge"],
        law: "trespass2",
        spec: "Entered and remained on the premises of {V}, a farmer, after being notified not to enter, on {DATE}.",
        ages: 25...68,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V}, a farmer, found {D} in a tree stand on {V}'s posted farmland on {DATE}. {V} had told {DL} to stay off the land. {DL} says the stand was on a neighbor's land with permission.",
        state: [E(.physical, 3, "Posted Signs", "Bright signs at the tree line within sight of the stand.", .search), E(.statement, 2, "Farmer", "{V} says {D} was told twice not to hunt the land.")],
        defense: [E(.statement, 1, "Neighbor's Permission", "{DL} says the stand was on a neighbor's tract with permission.")],
        role: "Farmer",
        exam: [.direct("What is your farm?", "\"I run a farm with several hundred acres of crops and woods, which I keep posted against hunting.\""), .direct("What did you find on your land?", "\"A man in a tree stand near the edge of my woods, with a rifle, well inside the posted line.\""), .direct("Who was it?", "\"{DL}, who I had already told, twice, not to hunt on my land.\""), .direct("What were the signs like?", "\"Bright orange signs at the tree line, in plain view of the stand, saying 'No hunting or trespassing.'\""), .direct("What did you do?", "\"I called the sheriff's office and waited at the stand until a deputy arrived.\""), .direct("What did {DL} say?", "\"{D.He} said the stand was on a neighbor's land, with the neighbor's permission.\""), .cross("The neighbor's land is next to yours?", "\"Yes, the neighbor's land runs along the north side of my farm, next to the ditch.\""), .cross("The line is hard to see?", "\"It runs along a ditch that's mostly overgrown, so it's easy to miss from the woods.\""), .cross("The stand has been there a while?", "\"It looks new, but I can't say when it went up.\""), .cross("{DL} didn't argue?", "\"No, {D.he} didn't argue. {D.He} climbed down from the stand and waited for the deputy.\""), .cross("The neighbor says {DL} had permission?", "\"The neighbor says so, but not for my side of the ditch.\"")],
        theory: ("{D} hunted posted land.", "A stand on a neighbor's land."),
        allocution: "\"I take responsibility for being near that farm. My stand was on my neighbor's land with permission, and I believed the line was where he said. I've been in this courtroom before about hunting, and I should have checked it myself.\"",
        truths: ("{DL} moved the stand fifty yards onto {V}'s land the day before.", "A survey puts the stand about ten feet inside the neighbor's tract."),
        defendant: [.direct("Did you hunt on the farmer's land?", "\"I hunted from a stand I thought was on my friend's tract, and I believed I had permission.\""), .direct("Who gave permission?", "\"The neighbor, my friend, who said I could hunt anywhere on the north side of the ditch.\""), .direct("Did you see the signs?", "\"I saw some signs, but I thought they marked the farmer's line, which I believed was farther south.\""), .direct("Did the farmer tell you not to hunt there?", "\"He told me not to hunt on his land, and I thought I was on my friend's land.\""), .direct("What did you do when the deputy came?", "\"I climbed down, and I showed {OFF.him} where the stand was, and I explained what I believed.\""), .direct("What would you tell the farmer?", "\"I'm sorry for crossing your line. I'll check every boundary before I hunt again.\""), .cross("You've been charged with hunting on posted land before, haven't you?", "\"Yes, and I told the court I'd always check. I thought this time I was on my friend's land.\""), .cross("The stand was within sight of bright signs?", "\"The sign was in plain view, and I should have looked more carefully before I climbed.\""), .cross("The farmer had told you twice not to hunt his land?", "\"He had, and I should have stayed far away from his side.\""), .cross("You'll check with the deputy where the line runs?", "\"Yes, I'll walk it with a deputy and a survey.\""), .cross("You'll take down the stand?", "\"Yes, I'll take down the stand today, and I won't hunt anywhere near that line.\"")],
        openings: ("{V}, a farmer, found {D} in a tree stand on {V}'s posted farmland after {V} had told {D} to stay off the land, and {DL} had been before this court in {PRIORDATE} over {PRIOR}.", "The defense will say the stand was on a neighbor's land with permission, and {D} believed the line was elsewhere. {D} did not mean to trespass."),
        closings: ("{V} told {D} to stay off the land, the land was posted, and {D} was found in a stand on it, and with {PRIOR} already on {D.his} record, {DL} knew exactly where the line was.", "A hunter on a neighbor's land with permission is not a trespasser. The State must prove the stand was on {V}'s land and that {D} knew."),
        timeline: [(-1, "The stand is moved."), (0, "Dawn: {V} finds {D}."), (0, "Deputies are called.")],
