        mood: .divided,
        genders: ["D": .male])

    static let copperTheftBack = SmallCases.make(
        key: "story.followup.copperTheftBack",
        category: .property,
        headlines: ["Catalytic Converters Found in Man's Shed, Deputies Say", "Substation Case Defendant Charged With Stolen Goods"],
        law: "possStolen",
        spec: "Possessed twelve stolen catalytic converters valued at $5,400, knowing them to be stolen, on {DATE}.",
        ages: 26...52,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, deputies with a search warrant found twelve catalytic converters in {D}'s shed on {DATE}, six matching theft reports. {DL} says {D.he} bought them as scrap from a man at a flea market.",
        state: [E(.physical, 3, "Converters in Shed", "Twelve converters, six with serials matching theft reports.", .search), E(.document, 2, "Theft Reports", "Six reports from a car dealership lot with serial numbers.")],
        defense: [E(.statement, 1, "Flea Market Buy", "{DL} says {D.he} bought them from a stranger as scrap.")],
        role: "Deputy",
        exam: [.direct("What is your assignment?", "\"I'm a deputy, and I was part of a team that searched a shed under a warrant.\""), .direct("What was the warrant for?", "\"A series of catalytic converter thefts from cars at a dealership, which had left many vehicles undrivable.\""), .direct("What did you find in the shed?", "\"Twelve catalytic converters stacked on a workbench, along with a saw and a jack.\""), .direct("How many matched theft reports?", "\"Six of the twelve had serial numbers that matched converters reported stolen from the dealership.\""), .direct("What were they worth?", "\"About fifty-four hundred dollars in scrap value, with higher replacement cost for the owners.\""), .direct("What did {DL} say?", "\"{D.He} said {D.he} bought the converters as scrap from a man at a flea market.\""), .cross("Scrap converters are sold at flea markets?", "\"Sometimes, but not with serial numbers that match reports of cars that were robbed.\""), .cross("{DL} didn't try to hide them?", "\"No, they were out in the open on the workbench.\""), .cross("{DL} gave you a description of the seller?", "\"A vague one, with no name and no address, so we have little to go on.\""), .cross("{DL} has a scrap business?", "\"{D.He} says so, but I saw no records or receipts of any kind in the shed.\""), .cross("The other six didn't match any reports?", "\"Not yet, but we're still checking the other six against the dealership's reports.\"")],
        theory: ("{D} held stolen parts.", "Scrap bought without knowing."),
        allocution: "\"I should have known better than to buy those converters from a man at a flea market. I thought they were ordinary scrap, and I never asked where they came from. I've been in this courtroom before, and I'm sorry for the owners of the cars. I'll cooperate to return them.\"",
        truths: ("{DL} paid $50 apiece, far under scrap value, in cash with no receipt.", "The seller later gave a name that matches a flea-market vendor card in {DL}'s wallet."),
        defendant: [.direct("Did you steal the converters?", "\"No. I bought them from a man at a flea market, thinking they were scrap from junked cars.\""), .direct("What did you pay?", "\"About a hundred dollars each, which seemed low, but I thought he wanted to get rid of them.\""), .direct("Did you know they were stolen?", "\"No. I'm a scrap dealer, and I buy parts all the time. I never asked about the source.\""), .direct("Why was a saw in your shed?", "\"I use it for cutting pipe and metal for scrap. It's a normal tool in my work.\""), .direct("What did you do when the deputies found them?", "\"I told them where I'd bought them, and I described the man as best I could.\""), .direct("What would you tell the dealership?", "\"I'm sorry for your loss. I didn't know the converters were yours, and I'll give them back.\""), .cross("You've been convicted of possessing stolen property before, haven't you?", "\"Yes, and I told the court I'd always check where parts come from. I didn't check these.\""), .cross("Six of the twelve have serial numbers matching theft reports?", "\"They do, and I can't explain how I missed that.\""), .cross("You bought twelve converters from a stranger with no receipt?", "\"I did buy twelve converters from a stranger with no receipt, and that was careless.\""), .cross("You'll give the deputy a full description of the seller?", "\"Yes, I'll describe the seller in detail, and I'll look at any photos the deputy has.\""), .cross("You'll return every converter to the dealership?", "\"Yes, I'll return every converter to the dealership, today, and pay for any I sold.\"")],
        openings: ("Deputies with a search warrant found twelve catalytic converters in {D}'s shed, six matching theft reports, and {DL} had stood in this court in {PRIORDATE} over {PRIOR}.", "The defense will say {D} bought them as scrap from a man at a flea market and did not know any were stolen. {D} bought and sold scrap openly."),
        closings: ("Twelve converters were in {D}'s shed and six match theft reports, and having faced {PRIOR} before, {DL} understood exactly what a pile of converters means.", "A scrap dealer who buys from a man at a flea market cannot trace each part. The State must prove {D} knew the six were stolen."),
        timeline: [(-8, "Converters are cut from dealer cars."), (0, "The search warrant."), (1, "{D} is charged.")],
        identified: "Theft report serials.",
        mood: .wantsConviction,
        genders: ["D": .male])

    static let bingoHallBack = SmallCases.make(
        key: "story.followup.bingoHallBack",
        category: .whiteCollar,
        headlines: ["Fake Fire Department Fund Collected Cash From Shop Owners", "Bingo Treasurer Back in Court on Fraud Charge"],
        law: "falsePretenses",
