        ages: 58...82,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} collected $1,500 from {V}, a shop owner, in November, saying it was for a new fire truck fund. The fire department had no such fund. {DL} says {D.he} meant to start one and the money is in an envelope.",
        state: [E(.statement, 3, "Fire Chief", "The chief says the department runs no such fund and sent no one."), E(.document, 2, "Receipt Book", "A receipt book with {D}'s writing for {V}'s $1,500.")],
        defense: [E(.physical, 1, "Envelope of Cash", "An envelope holding about $1,400 in cash.")],
        role: "Shop owner",
        exam: [.direct("What is your business?", "\"I own a small shop in town, and I try to support local causes when they ask.\""), .direct("What did {DL} ask you for?", "\"A donation for a new fire truck fund for the volunteer fire department, which {D.he} said was collecting money in November.\""), .direct("How much did you give?", "\"Fifteen hundred dollars in cash, because the cause sounded important and {DL} seemed sincere.\""), .direct("Did you get a receipt?", "\"Yes, from a receipt book with {DL}'s handwriting, for fifteen hundred dollars.\""), .direct("What did the fire chief say?", "\"That the department runs no such fund and sent no one to collect money in my area.\""), .direct("What did the deputies find?", "\"An envelope with about fourteen hundred dollars in cash in {DL}'s possession.\""), .cross("{DL} wore a fire department shirt?", "\"I don't think so, but {D.he} spoke as if {D.he} belonged to the department.\""), .cross("Other businesses gave?", "\"I heard several did, and I haven't heard how much.\""), .cross("{DL} told you where the money would go?", "\"Into a fund for a new truck, held at the bank.\""), .cross("You didn't verify the fund?", "\"No, I didn't verify the fund with the fire department, because I trusted {D.him} at the time.\""), .cross("You haven't been repaid?", "\"Not yet, although some of the money was recovered when deputies found the envelope.\"")],
        theory: ("{D} collected money for a fund that did not exist.", "A fund {D} meant to start."),
        allocution: "\"I took that fifteen hundred dollars meaning to start a fire truck fund, and it's in an envelope. I've been in this courtroom before, and I should have gotten the department's approval first. I'll return every dollar to {V}.\"",
        truths: ("{DL} spent $400 of the money on a casino trip, a bank record shows.", "{DL} had written the fire chief about starting a fund the week before."),
        defendant: [.direct("Did you collect money for a fire fund?", "\"I collected money, and I meant to start a fund. I told people it was for a truck.\""), .direct("Did the fire department know?", "\"No. I planned to ask them after I had enough money to show them.\""), .direct("Why did you say it was an existing fund?", "\"I thought saying it already existed would make people more willing to give.\""), .direct("Where is the money?", "\"About fourteen hundred dollars is in an envelope, which the deputy took. The rest I spent.\""), .direct("What did you spend it on?", "\"Gas, food, and a bill. I'm ashamed of that, and I'll account for every dollar.\""), .direct("What would you tell the shop owner?", "\"I'm sorry for misleading you. I'll repay the whole amount.\""), .cross("You've been charged with false solicitation before, haven't you?", "\"Yes, and I made a promise to the court then that I haven't kept. I'm ashamed.\""), .cross("You had no authority from the fire department?", "\"I had no authority from the fire department, and I shouldn't have used their name at all.\""), .cross("You kept the money instead of putting it in a fund?", "\"I did keep the money instead of putting it in a fund, and I can't excuse it.\""), .cross("You'll repay the shop owner?", "\"Yes, I'll repay the shop owner in full, and the others who gave me money too.\""), .cross("You'll stop collecting money?", "\"Yes, I'll stop collecting money for any cause, unless I'm sponsored by a real group.\"")],
        openings: ("{D} collected $1,500 from {V}, a shop owner, in November, saying it was for a new fire truck fund, and the fire department had no such fund, and {DL} had already appeared here in {PRIORDATE} over {PRIOR}.", "The defense will say {D} meant to start a fund and the money is in an envelope waiting for it. {D} did not spend a dollar."),
        closings: ("The fire department had no such fund, {V} paid $1,500, and since {PRIOR}, {DL} could not have missed what collecting money for a fund requires.", "A fund that has not yet started is a plan, not a fraud, and the money is in an envelope. The State must prove {D} never meant to start it."),
        timeline: [(-7, "{D} writes the fire chief."), (0, "{D} collects from {V}."), (30, "The chief hears of it.")],
