    static let deedForgeryBack = SmallCases.make(
        key: "story.followup.deedForgeryBack",
        category: .whiteCollar,
        headlines: ["Forged Lien Release Handed to Title Clerk", "Deed Forgery Defendant Faces Second Uttering Charge"],
