        ages: 34...68,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} handed {V}, a title clerk, a lien release on {DATE} to clear a lot for sale. The lender said it never signed it. {DL} says a notary gave {D.him} the paper.",
        state: [E(.document, 3, "Lien Release", "A release bearing the lender's stamp and a signature the lender disowns."), E(.statement, 2, "Lender Officer", "The lender's officer says the signature is not an employee's.")],
        defense: [E(.statement, 1, "Notary's Paper", "{DL} says a notary supplied the release.")],
        role: "County title clerk",
        exam: [.direct("What is your position?", "\"I'm a title clerk for the county, and I review documents that clear liens on property.\""), .direct("What did {DL} bring in?", "\"A lien release for a lot that {D.he} wanted to sell, stamped with a lender's seal and signed by an officer.\""), .direct("What made you suspicious?", "\"The signature looked traced, and the stamp was slightly crooked compared with the lender's usual releases.\""), .direct("What did you do?", "\"I called the lender, and an officer told me they never signed the release and never saw {DL}.\""), .direct("What does the release show?", "\"The lender's stamp, a signature the lender disowns, and the date, which was before {DL} came in.\""), .direct("What did {DL} say?", "\"{D.He} said a notary gave {D.him} the paper and that {D.he} thought it was real.\""), .cross("Notaries do handle documents?", "\"They do handle many documents, but not lien releases that come from a lender.\""), .cross("{DL} didn't fight when you questioned it?", "\"No, {D.he} didn't argue with me. {D.He} left the office quietly and didn't come back.\""), .cross("The notary has been identified?", "\"{DL} gave a notary's name, and the person denies giving {D.him} any such paper.\""), .cross("The lot was for sale?", "\"Yes, the lot was for sale, and {D.he} had a buyer lined up and waiting.\""), .cross("The lender's stamp was a copy?", "\"It looked like a copy of one of the lender's real stamps, but slightly off.\"")],
        theory: ("{D} offered a forged release.", "A notary's mistake."),
        allocution: "\"A notary gave me that lien release, and I handed it to the title clerk believing it was real. I've been in this courtroom before about a deed, and I know how it looks. I'm sorry, and I'll ask the lender to confirm.\"",
        truths: ("{DL} had a printout of the lender's stamp image on {DL}'s computer.", "The notary is real and confirms notarizing {DL}'s signature on a different form only."),
        defendant: [.direct("Did you forge the release?", "\"No. A notary gave me the paper, and I thought it was real. I never saw anyone sign it.\""), .direct("Who was the notary?", "\"A man at a small office in town. I gave his name, and I don't know why he denies it.\""), .direct("Why did you bring it to the clerk?", "\"I needed the lien cleared to sell the lot. A buyer was waiting.\""), .direct("Did you know it wasn't signed by the lender?", "\"No. If I had, I'd never have tried to use it. It looked official.\""), .direct("What did you do when the clerk said it was fake?", "\"I left, confused. I called the notary, and he didn't answer.\""), .direct("What would you tell the clerk and the lender?", "\"I'm sorry for the trouble. I didn't know it was fake.\""), .cross("You've been convicted of forging a document before, haven't you?", "\"Yes, and I said then that I'd never be back here again. I know why you doubt me.\""), .cross("The notary denies giving it to you?", "\"He does deny giving it to me, and I can't explain why he would say that.\""), .cross("You wanted to sell a lot with a lien on it?", "\"I did, and I should have called the lender myself.\""), .cross("You'll give the notary's address to the deputy?", "\"Yes, I'll give the notary's address and phone number to the deputy, today.\""), .cross("You'll cancel the sale?", "\"Yes, I'll cancel the sale of the lot, and I'll deal with the lender directly.\"")],
        openings: ("{D} handed {V}, a title clerk, a lien release to clear a lot for sale, and the lender said it never signed it, and this was not {DL}'s first time here, after {PRIOR} in {PRIORDATE}.", "The defense will say a notary gave {D} the paper, and {D} believed it was genuine. {D} did not forge the release, and relied on the notary's stamp as any layperson would."),
